def comps(inp,sep_rows,sep_cols):
    H,W=len(inp),len(inp[0])
    seen=[[False]*W for _ in range(H)]
    res=[]; stack=[]
    for r in range(H):
        for c in range(W):
            if inp[r][c]==5 and not seen[r][c] and r not in sep_rows and c not in sep_cols:
