                    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0<=x<H and 0<=y<W and not seen[x][y] and inp[x][y]==5:
                            seen[x][y]=True; Q.append((x,y))
                res.append(cells)
