def solve(inp):
    H,W=len(inp),len(inp[0])
    srows=[r for r in range(H) if all(x==0 for x in inp[r])]
    scolss=[c for c in range(W) if all(inp[r][c]==0 for r in range(H))]
    out=[row[:] for row in inp]
    cs=comps(inp,srows,scolss)
    for comp in cs:
        nb=set()
        for r,c in comp:
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                x,y=r+dr,c+dc
                if 0<=x<H and 0<=y<W and inp[x][y] not in (0,5):
                    nb.add(inp[x][y])
        val=min(nb)
        for r,c in comp: out[r][c]=val
    return out

